    ('mail_configuration_test', '[TEST] Email Configuration Test from {app_name}', '<h1>Test Email</h1><p>Hello <strong>{username}</strong>,</p><p>This message was sent to verify the email configuration for {app_name}.</p><p>Recipient: {email}<br>Queued at: {time} UTC</p><p><a href="{app_url}">{app_name}</a></p>'),
    ('node_alert_backup_failed', '{app_name}: {title}', '<h2>{title}</h2>{error_detail}<p>Severity: {severity}<br>Time: {time} UTC</p><p><a href="{url}">Open node status in {app_name}</a></p><p style="color:#888;font-size:12px">Change node alert channels under Admin, Nodes, Status.</p>'),
