    ('security_new_login', '{app_name}: new sign-in to your account', '<h2>New sign-in to your account</h2><p>Your {app_name} account was just signed in to from a new IP address.</p><p>IP address: {ip_address}<br>Device: {device}<br>Time: {time} UTC</p><p>If this was you, no action is needed. If not, change your password and enable two-factor authentication right away.</p>'),
    ('server_created', '{app_name}: Server created', '<h2>Server created</h2><p>Hello {username},</p><p><a href="{dashboard_url}">Open {app_name}</a></p>'),
    ('server_deleted', '{app_name}: Server deleted', '<h2>Server deleted</h2><p>Hello {username},</p><p><a href="{dashboard_url}">Open {app_name}</a></p>'),
    ('server_inactive_archive', '{app_name}: {server_name} is inactive', '<p>Hello {username},</p><p>Your server <strong>{server_name}</strong> has not been used for {days} days. If it stays unused, it will be backed up and then deleted after {due_at} UTC.</p><p>To keep it, open it and use it (start it, open the console or the files) before then.</p><p><a href="{url}">Open {server_name}</a></p>'),
    ('server_inactive_delete', '{app_name}: {server_name} is inactive', '<p>Hello {username},</p><p>Your server <strong>{server_name}</strong> has not been used for {days} days. If it stays unused, it will be deleted after {due_at} UTC.</p><p>To keep it, open it and use it (start it, open the console or the files) before then.</p><p><a href="{url}">Open {server_name}</a></p>'),
    ('server_inactive_notify', '{app_name}: {server_name} is inactive', '<p>Hello {username},</p><p>Your server <strong>{server_name}</strong> has not been used for {days} days. This is only a reminder.</p><p>To keep it, open it and use it (start it, open the console or the files) before then.</p><p><a href="{url}">Open {server_name}</a></p>'),
    ('server_inactive_suspend', '{app_name}: {server_name} is inactive', '<p>Hello {username},</p><p>Your server <strong>{server_name}</strong> has not been used for {days} days. If it stays unused, it will be suspended after {due_at} UTC.</p><p>To keep it, open it and use it (start it, open the console or the files) before then.</p><p><a href="{url}">Open {server_name}</a></p>'),
